import{z as o,x as A,o as r,c as d,q as n,j as E,D as e,d as i,s as l,S as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Gârleanu–Pedersen 动态交易","description":"","frontmatter":{"title":"Gârleanu–Pedersen 动态交易","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/garleanu-pedersen.md","filePath":"quant/garleanu-pedersen.md","lastUpdated":1791063341000}'),B={name:"quant/garleanu-pedersen.md"};function m(p,a,h,u,_,c){const t=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=n('<h1 id="garleanu–pedersen-动态交易" tabindex="-1">Gârleanu–Pedersen 动态交易 <a class="header-anchor" href="#garleanu–pedersen-动态交易" aria-label="Permalink to &quot;Gârleanu–Pedersen 动态交易&quot;">​</a></h1><div class="epigraph"><p>目标仓位在动、冲击是当前交易量的二次型时，最优是向一个瞄准点做部分调整，而不是一步买到信号目标。</p><footer>—— Gârleanu and Pedersen, Dynamic Trading with Predictable Returns and Transaction Costs, Journal of Finance, 2013</footer></div><p><a href="/quant/dynamic-programming-rebalance">上一课</a>给出带费用的 DP 结构。Gârleanu–Pedersen（GP）的缺口是给出<strong>可算的线性政策</strong>：超额收益可预测、价格冲击为 \\(\\frac12\\Lambda \\Delta x\\) 二次，目标函数是均值方差减冲击。主干 <a href="/quant/almgren-chriss">Almgren–Chriss</a> 处理一次性执行；GP 处理持续的 alpha 流。本课不重写冲击核。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>信号给出理想仓 \\(aim_t\\propto \\mathrm{forecast}_t\\)。若一步到位，冲击把 alpha 吃光，且明天信号又变，等于反复付冲击。GP 的解：交易朝着一个<strong>更平滑的瞄准组合</strong>，速度由 \\(\\Lambda\\) 与风险厌恶、以及信号的半衰期决定。问题是把「部分仓位」从经验规则（每次调 20%）升级为最优控制的增益矩阵，并能用同一套 \\(\\Lambda\\) 去解释容量。</p><p>与无交易带的差别：线性冲击 + 二次风险下，最优是连续的部分调整，不是「不动直到边界」。两种费用函数，两种政策形态。不要用 GP 去解释固定佣金下的阈值规则，也不要用 Constantinides 带去解释二次冲击的高频调仓。</p><h3 id="瞄准点不是信号目标" tabindex="-1">瞄准点不是信号目标 <a class="header-anchor" href="#瞄准点不是信号目标" aria-label="Permalink to &quot;瞄准点不是信号目标&quot;">​</a></h3><p>GP 的瞄准点是当前信号与未来预期信号的加权（因为未来还要交易）。快衰减信号的瞄准更靠近当前；慢信号可以更早布局。把瞄准点设成「今天的截面排序目标」，等于假设信号是白噪声未来，会交易过度。</p><p><span class="marginnote">\\(\\Lambda\\) 应来自冲击模型校准，见 <a href="/quant/sqrt-impact">平方根冲击</a> 与 Almgren。用换手惩罚乱凑一个 \\(\\Lambda\\)，政策增益没有经济单位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>状态：当前仓 \\(x_t\\)、信号向量。政策：\\(x_{t+1}-x_t=A(\\tilde x_t-x_t)\\)，其中 \\(\\tilde x\\) 是瞄准，\\(A\\) 是增益（可以按特征因子化）。估计：信号用衰减 AR；\\(\\Lambda\\) 用执行数据；风险用因子 \\(\\Sigma\\)。实现：在因子空间做 GP，再映射到股票，避免 \\(N\\times N\\) 冲击矩阵。对照：静态 Markowitz 每期重做 vs GP 路径，比较扣冲击后的 IR。</p>',11)),(r(),E(s,null,{default:e(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20SigData%5B%22%E5%8E%86%E5%8F%B2%E4%BF%A1%E5%8F%B7%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20AR%5B%22%E8%A1%B0%E5%87%8F%20AR%20%E6%8B%9F%E5%90%88%22%5D%0A%20%20Exec%5B%22%E6%89%A7%E8%A1%8C%E4%B8%8E%E6%88%90%E4%BA%A4%E9%87%8F%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20Lam%5B%22%E6%A0%A1%E5%87%86%E5%86%B2%E5%87%BB%E7%9F%A9%E9%98%B5%20%CE%9B%22%5D%0A%20%20Fac%5B%22%E5%9B%A0%E5%AD%90%E5%8D%8F%E6%96%B9%E5%B7%AE%22%5D%20--%3E%20Risk%5B%22%E9%A3%8E%E9%99%A9%E6%A8%A1%E5%9E%8B%20%CE%A3%22%5D%0A%20%20AR%20--%3E%20Aim%5B%22%E5%B9%B3%E6%BB%91%E7%9E%84%E5%87%86%E7%82%B9%20tilde%20x%22%5D%0A%20%20Lam%20--%3E%20Gain%5B%22%E6%B1%82%E8%A7%A3%E5%A2%9E%E7%9B%8A%20A%22%5D%0A%20%20Risk%20--%3E%20Gain%0A%20%20Aim%20--%3E%20Policy%5B%22%E6%AF%8F%E6%9C%9F%E5%8F%AA%E8%A1%A5%20A%20%E6%AF%94%E4%BE%8B%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20Gain%20--%3E%20Policy%0A%20%20Policy%20--%3E%20Eval%5B%22%E5%AF%B9%E6%AF%94%E9%9D%99%E6%80%81%20Markowitz%20%E7%9A%84%E6%89%A3%E8%B4%B9%20IR%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p><span class="marginnote">「增益 \\(A\\)」翻译成大白话就是：每期只把当前仓位与目标之间的缺口补上一部分，而不是一口吃成。数字实例：若 \\(A=0.2\\)，缺口按每期 \\(0.8\\) 倍缩小，五期后大约只剩 \\(0.8^5\\approx 33\\%\\)；\\(A\\) 越小走得越慢，付的冲击费越少，但 alpha 也衰减得越多。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>二次成本使交易像在粘性介质里移动仓位；最优是指数逼近，时间常数 \\(\\sqrt{\\lambda_{\\mathrm{risk}}/\\lambda_{\\mathrm{cost}}}\\) 一类。可预测收益提供漂移项，把稳态从 0 拉到正的风险暴露。容量：\\(\\Lambda\\) 随 AUM 涨，增益下降，稳态暴露下降——与 <a href="/quant/strategy-capacity">策略容量</a> 同向。</p><p><span class="marginnote">「粘性介质」可以想象成把铁球泡在糖浆里拖动：拖得越猛，阻力费越大，所以最优策略不是一步拖到位，而是匀速渐进。可预测收益像一个恒定的小水流，把球从中心慢慢推向某个偏移位置——这个偏移就是稳态上的 alpha 暴露。</span></p>',4)),(r(),E(s,null,{default:e(()=>[l(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Sig%5B%22%E5%8F%AF%E9%A2%84%E6%B5%8B%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20Aim%5B%22%E5%B9%B3%E6%BB%91%E7%9E%84%E5%87%86%E7%82%B9%22%5D%0A%20%20Lam%5B%22%E4%BA%8C%E6%AC%A1%E5%86%B2%E5%87%BB%20%CE%9B%22%5D%20--%3E%20Gain%5B%22%E9%83%A8%E5%88%86%E8%B0%83%E6%95%B4%E5%A2%9E%E7%9B%8A%22%5D%0A%20%20Risk%5B%22%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%22%5D%20--%3E%20Gain%0A%20%20Aim%20--%3E%20Trade%5B%22x%20%E6%96%B0%E5%87%8F%20x%20%E6%97%A7%22%5D%0A%20%20Gain%20--%3E%20Trade%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>冲击若是平方根而非二次，政策不再线性，GP 是近似。非线性约束（多空、行业）要投影，投影后失去最优性。信号若不可预测，GP 退化成缓慢向战略配置回归，等于带费用的再平衡，不是 alpha 引擎。</p><p><span class="marginnote">初学者容易把 GP 的线性公式当成万能调仓器。实际上整条结论都建立在「冲击成本是交易量的二次型」这一假设上；一旦真实冲击更像平方根（大单的边际成本递减），最优路径就不再是成比例的部分调整，公式只能当近似用。这一步假设错了，后面的增益估计就会系统性偏快。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GP 在二次冲击下给出向平滑瞄准点的部分调整，不是一步到信号目标。</li><li>瞄准点含未来信号预期；半衰期错了就会过交易。</li><li>\\(\\Lambda\\) 必须来自执行模型，增益才有单位。</li><li>出处：Gârleanu and Pedersen, <em>Journal of Finance</em>, 2013。</li></ul>',5))])}const D=o(B,[["render",m]]);export{f as __pageData,D as default};
